function makeLight() {
  let on = false;
  const toggle = () => {
    on = !on;
  };
  const state = () => (on ? "on" : "off");

  return [toggle, state, on];
}

const [toggle, state, on] = makeLight();

toggle();
console.log(state());
console.log(on);
toggle();
toggle();
console.log(state());
